double compute_relative_error(double numerical, double exact)
{
    if (exact == 0.0) {
        return numerical == 0.0 ? 0.0 : -1.0;  // Handle division by zero
    }
    double diff = numerical - exact;
    if (diff < 0) diff = -diff;
    double abs_exact = exact < 0 ? -exact : exact;
    return diff / abs_exact;
}

